{
  "title": "神秘的老宅",
  "scene": "你来到了一座古老的房子前，门半开着，里面很黑。墙上挂着一幅旧照片，照片里有个小男孩和一个老人在笑。院子里有一只大黄狗，看起来很友善。你记得村民们说过，老宅的主人十年前突然失踪了，留下了很多谜团。你决定进去看看。",
  "goal": "找到失踪主人的线索",
  "clue": "旧照片中的笑容和村民说主人失踪时的描述形成对比",
  "choices": [
    {
      "id": "A",
      "text": "直接进屋找线索",
      "outcome": "你走进屋内，四处寻找。突然，你听到一阵奇怪的声音，吓得你赶紧跑了出来。虽然你没有发现什么，但你感到老宅里确实有不寻常的事情发生。",
      "result": "fail",
      "next": "retry"
    },
    {
      "id": "B",
      "text": "先和大黄狗玩耍",
      "outcome": "你和大黄狗玩了一会儿，它带你来到房子后面的一个小花园。花园里有一块石碑，上面刻着失踪主人的名字。你发现了一些关于主人的日记，但花园的路很泥泞，你的鞋子全湿了。",
      "result": "partial",
      "next": "next_level"
    },
    {
      "id": "C",
      "text": "仔细观察旧照片",
      "outcome": "你仔细观察了旧照片，注意到照片中的小男孩和老人笑得很开心。你觉得这可能是关键，于是问了问村民关于照片的故事。一位老人告诉你，照片中的小男孩其实是主人的儿子，后来也失踪了。你找到了一条重要的线索，决定继续调查。",
      "result": "success",
      "next": "next_level"
    }
  ]
}
